h(\vec x, y) & = \begin{cases}
  g(\vec x, y, h(\vec x, k(\vec x, y))) & \text{if $k(\vec x, y) < y$} \\
  f(\vec x) & \text{otherwise}
\end{cases}

h(e, n) =
\begin{cases}
1 & \text{if computation $e$ halts on input $n$}\\
0 & \text{otherwise,}
\end{cases}
